import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Cosecha } from '../../cosechas/entities/cosecha.entity';
import { Agricultor } from '../../agricultores/entities/agricultor.entity';

@Injectable()
export class AsignarAgricultorRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Cosecha) private readonly cosechas: Repository<Cosecha>,
    @InjectRepository(Agricultor) private readonly agricultores: Repository<Agricultor>
  ) {}

  buscarCosechaRepository(cosechaId: number) {
    return this.cosechas.findOneBy({ id: cosechaId });
  }

  buscarAgricultorRepository(agricultorId: number) {
    return this.agricultores.findOneBy({ id: agricultorId });
  }

  async asignarAgricultorRepository(cosechaId: number, agricultorId: number, rol: string) {
    const asignacion = { cosechaId, agricultorId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarAgricultorRepository } from './repository';

@Injectable()
export class AsignarAgricultorService {
  constructor(private readonly repository: AsignarAgricultorRepository) {}

  async asignarAgricultorService(cosechaId: number, agricultorId: number, rol: string) {
    const cosecha = await this.repository.buscarCosechaRepository(cosechaId);
    const agricultor = await this.repository.buscarAgricultorRepository(agricultorId);
    if (!cosecha || !agricultor) {
      throw new NotFoundException('No existe la cosecha o el agricultor');
    }

    try {
      return await this.repository.asignarAgricultorRepository(cosechaId, agricultorId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El agricultor ya está asignado a esa cosecha');
      }
      throw error;
    }
  }
}

