import { buscarCosechaRepository, buscarAgricultorRepository, asignarAgricultorRepository } from './repository.mjs';

export class ReferenciaInexistenteError extends Error {}

export async function asignarAgricultorService(cosechaId, agricultorId, rol) {
  const cosecha = await buscarCosechaRepository(cosechaId);
  const agricultor = await buscarAgricultorRepository(agricultorId);
  if (!cosecha || !agricultor) {
    throw new ReferenciaInexistenteError('No existe la cosecha o el agricultor');
  }
  return asignarAgricultorRepository(cosechaId, agricultorId, rol);
}

import { asignarAgricultorService, ReferenciaInexistenteError } from './service.mjs';

export async function handler(event) {
  const cosechaId = Number(event.pathParameters.cosechaId);
  const { agricultorId, rol } = JSON.parse(event.body);
  try {
    const asignacion = await asignarAgricultorService(cosechaId, agricultorId, rol);
    return { statusCode: 201, body: JSON.stringify(asignacion) };
  } catch (error) {
    if (error instanceof ReferenciaInexistenteError) {
      return { statusCode: 404, body: JSON.stringify({ message: error.message }) };
    }
    if (error.name === 'ConditionalCheckFailedException') {
      return { statusCode: 409, body: JSON.stringify({ message: 'El agricultor ya está asignado a esa cosecha' }) };
    }
    throw error;
  }
}

